/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountLongPressPeek, type LongPressPeekOptions } from "../../components/long-press-peek/LongPressPeekEngine.js";
import type { MotionController } from "../../components/long-press-peek/motion-runtime";

export function LongPressPeek({ options, className }: { options?: LongPressPeekOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountLongPressPeek(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="long-press-peek" />;
}

